ound:#fff;color:#5b54ea;border-color:#d8d4ff}.pd-wish{background:#fff;color:#4f5b6d}.pd-wish.is-wishlisted{color:#e4475a;background:#fff5f6;border-color:#f3c8ce}.pd-related{padding-top:42px}.pd-related h2{margin:0 0 18px;color:#172033;font-size:26px}.pd-related-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.pd-related-card{background:#fff;border:1px solid #e7eaf0;border-radius:16px;padding:13px;text-decoration:none;color:inherit}.pd-related-cover{height:240px;border-radius:11px;background:#f6f7fa;display:flex;align-items:center;justify-content:center;overflow:hidden}.pd-related-cover img{width:100%;height:100%;object-fit:contain;padding:12px}.pd-related-name{margin-top:12px;font-weight:800;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pd-related-price{margin-top:7px;font-size:13px;font-weight:900;color:#172033}.pd-note{margin-top:14px;color:#7b8492;font-size:11px}@media(max-width:900px){.pd-card{grid-template-columns:1fr}.pd-cover-side{padding:32px}.pd-related-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.pd-page{padding-left:5%;padding-right:5%}.pd-info{padding:28px 20px}.pd-title{font-size:28px}.pd-actions{grid-template-columns:1fr}.pd-related-grid{grid-template-columns:1fr 1fr}.pd-cover-frame{height:360px}}
</style>
