</div></div>
<script>
document.addEventListener('DOMContentLoaded',function(){
 const id=<?= (int)$product['id']; ?>, add=document.getElementById('pdAdd'), buy=document.getElementById('pdBuy'), cartUrl=<?= json_encode(site_url('cart/add')); ?>, checkout=<?= json_encode(site_url('checkout')); ?>;
 function submitAdd(btn,next){const original=btn.innerHTML;btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner"></i> Adding...';fetch(cartUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:'product_id='+encodeURIComponent(id)+'&quantity=1'}).then(r=>r.json()).then(d=>{if(d.redirect){location.href=d.redirect;return;}if(!d.success)throw new Error(d.message||'Could not add to cart.');const c=document.getElementById('cartCount');if(c)c.textContent=d.cart_count;if(next)location.href=checkout;else{btn.innerHTML='<i class="fa-solid fa-check"></i> Added to Cart';setTimeout(()=>{btn.disabled=false;btn.innerHTML=original},1200);}}).catch(e=>{alert(e.message);btn.disabled=false;btn.innerHTML=original});}
 add&&add.addEventListener('click',()=>submitAdd(add,false)); buy&&buy.addEventListener('click',()=>submitAdd(buy,true));
 document.addEventListener('wishlist:updated',function(e){if(e.detail&&Number(e.detail.productId)===id){const b=document.querySelector('.pd-wish'),icon=b?.querySelector('i'),txt=b?.querySelector('span');if(b){b.classList.toggle('is-wishlisted',!!e.detail.added);b.setAttribute('aria-pressed',e.detail.added?'true':'false');if(icon){icon.classList.toggle('fa-solid',!!e.detail.added);icon.classList.toggle('fa-regular',!e.detail.added)}if(txt)txt.textContent=e.detail.added?'Remove from Wishlist':'Add to Wishlist';}}});
});
</script>
